<form method="post" action="/tickets/<?= (int)$ticket['id'] ?>/comments" class="stack"><?= csrf() ?><input type="hidden" name="_return" value="/tickets/<?= (int)$ticket['id'] ?>"><div class="rich-composer" data-composer data-upload-url="/tickets/<?= (int)$ticket['id'] ?>/attachments">
